// Server-side vehicle table (generated by tools/gen-vehicles.mjs). Model index on the wire = position + 1, 0 = on foot.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { VCLASS } from '../../src/net/shared/constants.js';

const here = path.dirname(fileURLToPath(import.meta.url));

// Movement limits per class. h = max horizontal speed (m/s), up/down = vertical speed (m/s), alt = max height above
// ground/sea for that class (m), climb = sustained climb allowed per 6 s window (m).
export const CLASS_LIMITS = {
  [VCLASS.FOOT]: { h: 14, up: 30, down: 140, alt: 300, climb: 40 },
  [VCLASS.CAR]: { h: 95, up: 45, down: 140, alt: 300, climb: 120 },
  [VCLASS.BIKE]: { h: 95, up: 45, down: 140, alt: 300, climb: 120 },
  [VCLASS.HELI]: { h: 110, up: 60, down: 160, alt: 2900, climb: 1e9 },
  [VCLASS.PLANE]: { h: 320, up: 120, down: 250, alt: 2900, climb: 1e9 },
  [VCLASS.BOAT]: { h: 50, up: 30, down: 140, alt: 120, climb: 60 },
};

export function loadVehicles(file = process.env.VEHICLES_PATH || path.resolve(here, '../data/vehicles.json')) {
  const raw = JSON.parse(fs.readFileSync(file, 'utf8')).vehicles;
  const models = [null]; // index 0 = foot
  const byId = new Map();
  for (const v of raw) {
    const m = {
      index: models.length, id: v.id, kind: v.kind, vclass: v.vclass, traffic: !!v.traffic,
      // speed limit: catalog top speed with margin for nitro, downhill and tuning; capped by the class
      vmax: Math.min(CLASS_LIMITS[v.vclass]?.h ?? 95, (v.topSpeedKmh / 3.6) * (v.vclass === VCLASS.PLANE || v.vclass === VCLASS.HELI ? 1.4 : 1.35) + 8),
    };
    models.push(m);
    byId.set(v.id, m);
  }
  return { models, byId, raw, count: models.length - 1, list: raw.map((v) => ({ id: v.id, vclass: v.vclass })) };
}
